            figs/methodfig.pdf
        }
        \vspace{-0.5cm}
        \caption{Subtask illustration of the recursive subtasks. The optimal results at timestep $j$ using $i$ step denosing ($z[i][j]$) derives from the $i-1$ step optimal denosing results($z[i-1]$).}
