\title{``Principal Components" Enable A New Language of Images}

\author{
Xin Wen$^{1*}$ \authorskip Bingchen Zhao$^{2*\dagger}$ \authorskip Ismail Elezi$^{3}$ \authorskip Jiankang Deng$^{4}$ \authorskip Xiaojuan Qi$^1$$^\ddagger$\vspace{.1em}  \\
